namespace RobloxAntiAfk.Core.Localization;

/// <summary>Английские тексты. Ключ это русский текст из интерфейса: тесты проверяют, что перевод есть у каждого.</summary>
internal static class EnglishTexts
{
    public static readonly IReadOnlyDictionary<string, string> All = new Dictionary<string, string>
    {
        ["Пробел"] = "Space",
        ["Правый клик"] = "Right click",
        ["Левый клик"] = "Left click",
        ["Клавиша"] = "Key",
        ["Шаг W → S"] = "Step W → S",
        ["Зум I → O"] = "Zoom I → O",
        ["Свой макрос"] = "Custom macro",
        ["Клавиша {0}"] = "{0} key",
        ["Нажимает выбранную клавишу в окне Roblox."] = "Presses the selected key in the Roblox window.",
        ["Нажимает W, а затем S в окне Roblox."] = "Presses W, then S in the Roblox window.",
        ["Нажимает I, а затем O в окне Roblox."] = "Presses I, then O in the Roblox window.",
        ["Повторяет записанные тобой нажатия и движения в окне Roblox."] = "Repeats the keys and clicks you recorded in the Roblox window.",
        ["Кликает в выбранную точку окна Roblox."] = "Clicks the chosen point in the Roblox window.",
        ["Кликает по центру окна Roblox."] = "Clicks the center of the Roblox window.",
        ["Может задеть игру"] = "May affect the game",
        ["Левый клик может нажать кнопку на экране, выстрелить или ударить. Курсор сразу возвращается на место."] = "A left click can press an on-screen button, shoot, or hit something. The cursor returns right away.",
        ["Клавиша нажимается по-настоящему: W, A, S, D двигают персонажа, Пробел прыгает, цифры меняют предмет. Если открыт чат, символ попадёт в него."] = "The key is really pressed: W, A, S, D move your character, Space jumps, numbers switch items. If chat is open, the character goes into it.",
        ["Персонаж двигается"] = "Your character moves",
        ["Персонаж делает короткий шаг вперёд и назад. Это может помочь в играх со своим таймером, но не гарантия. Рядом с препятствием он может немного сместиться. Если открыт чат, буквы попадут в него."] = "Your character takes a short step forward and back. This may help in games with their own timer, but it isn't guaranteed. Near an obstacle it may shift slightly. If chat is open, the letters go into it.",
        ["Двигается только камера"] = "Only the camera moves",
        ["Камера немного приближается и отдаляется обратно, персонаж стоит на месте. Если открыт чат, буквы попадут в него."] = "The camera zooms in a little and back out while your character stays put. If chat is open, the letters go into it.",
        ["Запись повторяется как есть. Если персонаж стоит в другом месте или открыт чат, результат будет другим. Поворот камеры может повториться неточно."] = "The recording repeats as is. If your character is somewhere else or chat is open, the result will differ. Camera turns may not repeat exactly.",
        ["Не мешает игре"] = "Doesn't interfere with the game",
        ["Правый клик не нажимает кнопки, не стреляет и не двигает персонажа. Курсор сразу возвращается на место."] = "A right click doesn't press buttons, shoot, or move your character. The cursor returns right away.",
        ["Пропуск: идёт игра"] = "Skipped: game in progress",
        ["Не удалось переключиться на Roblox"] = "Couldn't switch to Roblox",
        ["Окно Roblox свёрнуто, разверни его"] = "Roblox window is minimized, restore it",
        ["Точка сохранена"] = "Point saved",
        ["Выбор точки отменён"] = "Point selection canceled",
        ["Не удалось начать выбор точки"] = "Couldn't start point selection",
        ["Сначала запусти Roblox"] = "Start Roblox first",
        ["Сначала выдай разрешение"] = "Grant the permission first",
        ["Персонаж сброшен"] = "Character reset",
        ["Макрос записан"] = "Macro recorded",
        ["В окне Roblox ничего не нажато, макрос не изменён"] = "Nothing was pressed in the Roblox window, macro unchanged",
        ["Сначала запиши макрос в настройках"] = "Record a macro in the settings first",
        ["Не удалось начать запись"] = "Couldn't start recording",
        ["Окно Roblox закрылось"] = "Roblox window closed",
        ["Roblox отключился от сервера"] = "Roblox disconnected from the server",
        ["Захожу в игру снова"] = "Rejoining the game",
        ["Снова в игре"] = "Back in the game",
        ["Не получилось зайти за 5 попыток"] = "Couldn't rejoin after 5 attempts",
        ["Что-то пошло не так, попробую в следующий раз"] = "Something went wrong, will try again next time",
        ["Перевод выключен."] = "Translation is off.",
        ["Сначала выбери область."] = "Select an area first.",
        ["Готово. Нажми {0} в игре, когда появится текст."] = "Ready. Press {0} in the game when text appears.",
        ["Готово. Нажми {0} в игре и обведи текст."] = "Ready. Press {0} in the game and circle the text.",
        ["Жду, пока ты обведёшь текст."] = "Waiting for you to circle the text.",
        ["Читаю текст..."] = "Reading text...",
        ["Перевод показан. Чтобы убрать, кликни левой или правой кнопкой в окне Roblox или нажми {0}."] = "Translation shown. To remove it, left- or right-click in the Roblox window or press {0}.",
        ["Текст прочитан, но перевод сейчас недоступен. Проверь интернет."] = "Text was read, but translation is unavailable right now. Check your internet connection.",
        ["В выбранной области текст не найден."] = "No text found in the selected area.",
        ["Область слишком маленькая, выбери её заново."] = "The area is too small, select it again.",
        ["Сначала запусти Roblox."] = "Start Roblox first.",
        ["Не удалось вывести Roblox вперёд. Открой его и нажми ещё раз."] = "Couldn't bring Roblox to the front. Open it and press again.",
        ["Сначала выдай разрешение «Универсальный доступ»."] = "Grant the Accessibility permission first.",
        ["Нужно разрешение «Запись экрана»: Системные настройки → Конфиденциальность и безопасность → Запись экрана. Включи BloxPilot и открой приложение заново."] = "Screen Recording permission is required: System Settings → Privacy & Security → Screen Recording. Turn on BloxPilot and reopen the app.",
        ["Снимок окна получился пустым. Переключи Roblox в оконный режим и попробуй ещё раз."] = "The window capture came out empty. Switch Roblox to windowed mode and try again.",
        ["Не удалось начать выбор области."] = "Couldn't start area selection.",
        ["Не удалось прочитать текст."] = "Couldn't read the text.",
        ["Левый клик сделан"] = "Left click done",
        ["Нажата клавиша {0}"] = "Pressed the {0} key",
        ["Шаг W → S сделан"] = "Step W → S done",
        ["Зум I → O сделан"] = "Zoom I → O done",
        ["Макрос выполнен"] = "Macro finished",
        ["Правый клик сделан"] = "Right click done",
        ["{0} (окон: {1} из {2})"] = "{0} (windows: {1} of {2})",
        ["Что делает программа"] = "What the app does",
        ["Сначала нажми «Запустить»"] = "Press “Start” first",
        ["Приложение открывается выключенным и ничего не делает, пока ты сама его не запустишь. Остановить можно в любой момент той же кнопкой."] = "The app opens turned off and does nothing until you start it. You can stop it any time with the same button.",
        ["{0} раз в {1}"] = "{0} every {1}",
        ["{0} Обычно Roblox кикает примерно после 20 минут без действий. Всё это меняется в настройках."] = "{0} Roblox usually kicks you after about 20 minutes of inactivity. All of this can be changed in the settings.",
        ["Можно заниматься другими делами"] = "You can do other things",
        ["Если открыто другое окно, программа на секунду переключится на Roblox, сделает действие и вернёт тебя обратно. Если ты печатаешь, она подождёт паузу, но не дольше 30 секунд."] = "If another window is open, the app switches to Roblox for a second, does the action, and brings you back. If you're typing, it waits for a pause, but no longer than 30 seconds.",
        ["Пропускает действие, когда идёт игра"] = "Skips the action while you play",
        ["Если Roblox открыт и в последнюю минуту кто-то нажимал клавиши или двигал мышь, действие не нужно. Это можно выключить в настройках."] = "If Roblox is open and someone pressed keys or moved the mouse in the last minute, no action is needed. You can turn this off in the settings.",
        ["Работает со всеми окнами Roblox"] = "Works with all Roblox windows",
        ["Если открыто несколько окон, действие выполняется в каждом по очереди, с паузой в секунду. Если ты играешь в одном из них, это окно пропускается, но программа всё равно ненадолго переключится на остальные. Это можно выключить в настройках."] = "If several windows are open, the action runs in each one in turn, a second apart. If you're playing in one of them, that window is skipped, but the app still switches to the others briefly. You can turn this off in the settings.",
        ["Не даёт компьютеру уснуть"] = "Keeps your computer awake",
        ["Экран и компьютер не засыпают, пока приложение запущено. Это можно выключить в настройках, но во сне Roblox отключится."] = "The screen and computer don't sleep while the app is running. You can turn this off in the settings, but Roblox disconnects during sleep.",
        ["Что нужно для работы"] = "What it needs to work",
        ["Разрешение «Универсальный доступ»"] = "Accessibility permission",
        ["Системные настройки → Конфиденциальность и безопасность → Универсальный доступ → включи BloxPilot. Без него macOS не даст кликать и нажимать клавиши. Если там уже включено, а приложение всё равно просит разрешение, удали его кнопкой «−» и добавь снова."] = "System Settings → Privacy & Security → Accessibility → turn on BloxPilot. Without it, macOS won't allow clicks and key presses. If it's already on but the app still asks, remove it with the “−” button and add it again.",
        ["Окно Roblox не свёрнуто"] = "Roblox window isn't minimized",
        ["Свёрнутое окно приложение не разворачивает, а просто пропустит действие и напишет об этом. Оставь окно открытым, пусть даже за другими окнами."] = "The app doesn't restore a minimized window, it just skips the action and reports it. Keep the window open, even behind other windows.",
        ["Свёрнутое окно не помеха"] = "A minimized window is fine",
        ["Если Roblox свёрнут, приложение развернёт его на секунду, сделает действие и свернёт обратно."] = "If Roblox is minimized, the app restores it for a second, does the action, and minimizes it again.",
        ["Что важно знать"] = "Good to know",
        ["Некоторые игры кикают сами"] = "Some games kick on their own",
        ["У игры может быть свой таймер, который следит за движением персонажа. От такого кика клик на месте не спасёт. Может помочь режим «Шаг W → S» из настроек, но это не гарантия."] = "A game may have its own timer that watches character movement. A click in place won't help against that kick. “Step W → S” in the settings may help, but it isn't guaranteed.",
        ["Правила конкретной игры"] = "Rules of each game",
        ["Где-то стоять без дела запрещено правилами самой игры. Перед долгим AFK загляни в них."] = "Some games forbid standing idle. Check their rules before a long AFK session.",
        ["Если Roblox отключился"] = "If Roblox disconnects",
        ["Программа увидит запись об отключении в журнале Roblox и зайдёт по твоей ссылке, максимум 5 попыток подряд. Если закрыть окно самой, она обратно не зайдёт."] = "The app sees the disconnect record in the Roblox log and rejoins using your link, up to 5 attempts in a row. If you close the window yourself, it won't rejoin.",
        ["Сама программа в игру обратно не зайдёт, пока не включишь переподключение в настройках."] = "The app won't rejoin the game until you turn on reconnecting in the settings.",
        ["Как проверить"] = "How to check",
        ["Нажми «Запустить», а затем «Сделать сейчас»: в списке слева появится запись с зелёной точкой. Затем оставь Roblox примерно на 25 минут. Если не кикнуло, всё работает."] = "Press “Start”, then “Do it now”: an entry with a green dot appears in the list on the left. Then leave Roblox for about 25 minutes. If you weren't kicked, everything works.",
        ["Уведомления в Telegram"] = "Telegram notifications",
        ["Как подключить"] = "How to connect",
        ["Создай бота через @BotFather, напиши ему любое сообщение, вставь токен в настройках и нажми «Подключить». Придёт проверочное сообщение. Бот сообщит об отключении от сервера, пока приложение открыто, даже если оно не запущено кнопкой."] = "Create a bot with @BotFather, send it any message, paste the token in the settings, and press “Connect”. A test message will arrive. The bot reports server disconnects while the app is open, even if it wasn't started with the button.",
        ["Если нет интернета"] = "If there's no internet",
        ["Сообщение ждёт до 6 часов и уйдёт, когда связь появится. Если закрыть приложение раньше, неотправленные сообщения пропадут."] = "A message waits for up to 6 hours and is sent when the connection returns. If you close the app sooner, unsent messages are lost.",
        ["Если Telegram работает только с VPN"] = "If Telegram only works with a VPN",
        ["Без VPN бот не сможет отправить сообщение, но поможет бесплатный посредник на Cloudflare. Создай его один раз: зарегистрируйся на cloudflare.com, открой Workers & Pages, создай Worker на основе Hello World и нажми Deploy. Затем нажми Edit code, замени весь код на код из файла packaging/telegram-relay/worker.js в репозитории bone1nis/BloxPilot-for-Roblox на GitHub и снова нажми Deploy."] = "Without a VPN the bot can't send messages, but a free relay on Cloudflare can help. Create it once: sign up at cloudflare.com, open Workers & Pages, create a Worker from Hello World, and press Deploy. Then press Edit code, replace all the code with the code from packaging/telegram-relay/worker.js in the bone1nis/BloxPilot-for-Roblox repository on GitHub, and press Deploy again.",
        ["Как подключить посредника"] = "How to connect the relay",
        ["Скопируй адрес вида https://имя.твой-аккаунт.workers.dev. Выключи VPN и открой его в браузере: должно появиться «Посредник работает». Новый адрес может заработать не сразу, поэтому при ошибке безопасного подключения подожди пару минут и перезапусти браузер. Затем вставь адрес в поле посредника в настройках и нажми «Подключить»."] = "Copy the address that looks like https://name.your-account.workers.dev. Turn off your VPN and open it in a browser: you should see “Посредник работает” (the relay is working). A new address may not work right away, so if you get a secure connection error, wait a couple of minutes and restart the browser. Then paste the address into the relay field in the settings and press “Connect”.",
        ["Что важно про посредника"] = "About the relay",
        ["Токен бота проходит через посредника, поэтому указывай только своего. Если он указан, сообщения идут только через него. Если он перестал отвечать, очисти поле и включи VPN."] = "The bot token passes through the relay, so use only your own. If one is set, messages go only through it. If it stops responding, clear the field and turn on your VPN.",
        ["Перевод текста из игры"] = "Translating text from the game",
        ["Как это работает"] = "How it works",
        ["Приложение делает снимок выбранной части экрана, распознаёт на нём текст и показывает русский перевод. В Roblox ничего не внедряется и не меняется: это обычное чтение картинки с экрана. По умолчанию перевод выключен, включается на вкладке «Перевод»."] = "The app takes a snapshot of the selected part of the screen, recognizes the text, and shows a translation into the app language. Nothing is injected or changed in Roblox: it just reads a picture from the screen. Translation is off by default, turn it on in the “Translate” tab.",
        ["{0}, обвести текст, и готов перевод"] = "{0}, circle the text, get the translation",
        ["Нажми {0}, и картинка в окне Roblox замрёт, как при скриншоте. Зажми левую кнопку мыши и обведи текст: прочитается именно застывший кадр, поэтому движущийся текст не убежит. Этот клик в игру не попадёт. Сама игра при этом идёт дальше, и клавиши до неё доходят, кроме Esc. Перевод появится под выделением, а если там нет места, то над ним. Чтобы убрать перевод, кликни левой или правой кнопкой в любом месте окна Roblox или снова нажми сочетание. Этот клик в игру не попадёт, а клавиши работают как обычно. Потом всё можно повторить с другим текстом. Пока приложение ждёт выделения, его отменит Esc, правая кнопка мыши или ещё одно нажатие сочетания. Пока перевод включён, это сочетание не работает в других программах. Раскладка не важна."] = "Press {0} and the picture in the Roblox window freezes, like a screenshot. Hold the left mouse button and circle the text: the frozen frame is what gets read, so moving text won't get away. This click doesn't reach the game. The game itself keeps running and keys still reach it, except Esc. The translation appears below the selection, or above it if there's no room. To remove it, left- or right-click anywhere in the Roblox window or press the shortcut again. That click doesn't reach the game, and keys work as usual. Then you can repeat with other text. While the app waits for a selection, Esc, the right mouse button, or pressing the shortcut again cancels it. While translation is on, this shortcut doesn't work in other programs. Keyboard layout doesn't matter.",
        ["Сочетание можно поменять"] = "You can change the shortcut",
        ["На вкладке «Перевод» и в настройках можно поставить своё сочетание или одну клавишу. Одиночная клавиша не будет работать в игре и других программах, пока сочетание занято приложением. Esc без других клавиш поставить нельзя: он отменяет выделение."] = "In the “Translate” tab and in the settings you can set your own shortcut or a single key. A single key won't work in the game and other programs while the app holds it. Esc alone can't be used: it cancels selection.",
        ["Можно запомнить одно место"] = "You can remember one spot",
        ["Если текст всегда появляется в одном месте, выключи «Выделять каждый раз» и выбери область один раз. Тогда {0} сразу покажет перевод этого места. Область будет двигаться вместе с окном."] = "If text always appears in the same place, turn off “Select every time” and pick the area once. Then {0} immediately shows the translation of that spot. The area moves with the window.",
        ["Перевод может обновляться сам"] = "Translation can update itself",
        ["Если включить «Обновлять самому», пока перевод показан, область читается раз в 2 секунды. Текст исчез, и подпись прячется. Появился новый, и она показывается снова."] = "If you turn on “Auto-refresh”, the area is read every 2 seconds while a translation is shown. When the text disappears, the caption hides. When new text appears, it shows again.",
        ["Что уходит в интернет"] = "What goes online",
        ["Распознавание работает на компьютере, снимки никуда не отправляются и не сохраняются. В сервис перевода уходит только распознанный текст, но если в области окажется чат или ник, они уйдут тоже. Экран читается, только пока Roblox на переднем плане, поэтому текст из других окон туда не попадёт."] = "Recognition runs on your computer, snapshots are never sent or saved. Only the recognized text goes to the translation service, but if the area contains chat or a username, those go too. The screen is read only while Roblox is in front, so text from other windows doesn't get in.",
        ["Что читается плохо"] = "What reads poorly",
        ["Обычный текст диалогов и меню распознаётся хорошо. Декоративные шрифты, надписи на 3D-объектах и текст на пёстром фоне могут читаться с ошибками, а за быстро движущимся текстом перевод не успеет."] = "Regular dialog and menu text is recognized well. Decorative fonts, text on 3D objects, and text on busy backgrounds may be misread, and translation can't keep up with fast-moving text.",
        ["Вместо перевода подпись покажет исходный английский текст и напомнит проверить интернет."] = "Instead of a translation, the caption shows the original text and reminds you to check your internet connection.",
        ["Если подпись не видно"] = "If you can't see the caption",
        ["Переключи Roblox из полноэкранного режима в окно. На весь экран подпись показывается поверх игры, но значок приложения на это время пропадает из Dock: иначе macOS её не покажет."] = "Switch Roblox from fullscreen to a window. In fullscreen the caption appears over the game, but the app icon disappears from the Dock for that time: otherwise macOS won't show it.",
        ["Переключи Roblox из полноэкранного режима в окно. В некоторых режимах Windows не показывает другие окна поверх игры и не отдаёт её изображение."] = "Switch Roblox from fullscreen to a window. In some modes Windows doesn't show other windows over the game and doesn't provide its image.",
        ["Разрешение «Запись экрана»"] = "Screen Recording permission",
        ["Без него macOS не даст прочитать экран. Системные настройки → Конфиденциальность и безопасность → Запись экрана → включи BloxPilot и открой приложение заново."] = "Without it, macOS won't let the app read the screen. System Settings → Privacy & Security → Screen Recording → turn on BloxPilot and reopen the app.",
        ["Запущенный Roblox"] = "Roblox is running",
        ["Приложение можно открыть раньше игры, оно само найдёт окно Roblox."] = "You can open the app before the game, it finds the Roblox window on its own.",
        ["Экран не заблокирован"] = "Screen isn't locked",
        ["На заблокированном экране программа ничего не сможет нажать. Если закрыть крышку ноутбука, он может уснуть, и Roblox отключится."] = "The app can't press anything on a locked screen. If you close a laptop lid, it may go to sleep and Roblox will disconnect.",
        ["Приложение открыто"] = "The app is open",
        ["Закроешь окно, и всё остановится, если в настройках не включено «Прятать в трей». Настройки сохраняются, но при следующем открытии приложение снова будет выключено, если не включён запуск сразу."] = "If you close the window, everything stops, unless “Hide to tray” is on in the settings. Settings are saved, but next time the app opens turned off again, unless starting right away is on.",
        [" · по умолчанию"] = " · default",
        ["Не сбрасывать"] = "Don't reset",
        ["Раз в {0}"] = "Every {0}",
        ["По центру окна"] = "Window center",
        ["Своя точка"] = "Custom point",
        ["Русский"] = "Русский",
        ["Тёмная"] = "Dark",
        ["Светлая"] = "Light",
        ["Как в системе"] = "Same as system",
        ["Раскладка не важна: W нажмётся и на русской."] = "Keyboard layout doesn't matter: W works on any layout.",
        ["раз в {0}"] = "every {0}",
        ["Запас маленький: Roblox обычно кикает примерно через 20 минут."] = "Tight margin: Roblox usually kicks you after about 20 minutes.",
        ["По умолчанию раз в 5 минут. Roblox обычно кикает примерно через 20 минут."] = "Default is every 5 minutes. Roblox usually kicks you after about 20 minutes.",
        ["Отменить выбор"] = "Cancel selection",
        ["Выбрать другую точку"] = "Choose another point",
        ["Остановить запись"] = "Stop recording",
        ["Записать макрос"] = "Record macro",
        ["Записать заново"] = "Record again",
        ["{0} запускает и останавливает приложение из любого окна, а во время записи останавливает запись."] = "{0} starts and stops the app from any window, and stops a recording while one is running.",
        ["Сочетание {0} занять не удалось: его держит другая программа или система. Поставь другое."] = "Couldn't take the shortcut {0}: another program or the system holds it. Set a different one.",
        ["Подключено. Об отключении бот напишет, пока приложение открыто, о закрытии окна пока оно запущено. Без интернета сообщение уйдёт, когда он появится."] = "Connected. The bot reports disconnects while the app is open, and closed windows while it's running. Without internet, the message is sent when the connection returns.",
        ["Создай бота через @BotFather, вставь его токен, напиши боту любое сообщение и нажми «Подключить». Токен хранится на этом компьютере в файле настроек."] = "Create a bot with @BotFather, paste its token, send the bot any message, and press “Connect”. The token is stored on this computer in the settings file.",
        ["Необязательно. Посредник передаёт сообщения бота, когда Telegram закрыт без VPN. Как его создать, написано на вкладке «Как это работает»."] = "Optional. A relay passes bot messages when Telegram is blocked without a VPN. See the “How it works” tab for how to create one.",
        ["Нужен полный адрес вида https://имя.workers.dev. Пока сообщения идут напрямую."] = "A full address is required, like https://name.workers.dev. Messages go directly for now.",
        ["Сообщения идут через этот адрес, и токен бота проходит через него, поэтому указывай только своего посредника. Нажми «Подключить», чтобы проверить."] = "Messages go through this address and the bot token passes through it, so use only your own relay. Press “Connect” to check.",
        ["Это не похоже на токен. Скопируй его из сообщения @BotFather целиком."] = "That doesn't look like a token. Copy the whole token from the @BotFather message.",
        ["Проверяю..."] = "Checking...",
        ["BloxPilot подключён. Сюда придёт сообщение, если Roblox отключится или закроется."] = "BloxPilot connected. You'll get a message here if Roblox disconnects or closes.",
        ["Готово: проверочное сообщение отправлено."] = "Done: test message sent.",
        ["Чат найден, но сообщение не отправилось. Проверь интернет и нажми ещё раз."] = "Chat found, but the message wasn't sent. Check your internet connection and press again.",
        ["Telegram не принял этот токен. Скопируй его из сообщения @BotFather заново и целиком."] = "Telegram rejected this token. Copy the whole token from the @BotFather message again.",
        ["Сообщения этого бота уже забирает другая программа или сервис. Создай для уведомлений отдельного бота."] = "Another program or service is already reading this bot's messages. Create a separate bot for notifications.",
        ["Токен подходит, но новых сообщений нет. Открой {0}, напиши любое сообщение и сразу нажми ещё раз: Telegram хранит их только сутки."] = "The token works, but there are no new messages. Open {0}, send any message, and press again right away: Telegram only keeps them for a day.",
        ["Посредник не ответил как надо. Проверь адрес: если открыть его в браузере, должно быть написано «Посредник работает». Без посредника Telegram может работать через VPN."] = "The relay didn't respond correctly. Check the address: when opened in a browser, it should say “Посредник работает” (the relay is working). Without a relay, Telegram may work through a VPN.",
        ["Приложение не смогло связаться с Telegram (api.telegram.org). Интернет может работать, а этот адрес бывает закрыт у провайдера. Включи VPN для всего компьютера и нажми ещё раз или укажи адрес посредника ниже."] = "The app couldn't reach Telegram (api.telegram.org). Your internet may work while your provider blocks this address. Turn on a VPN for the whole computer and press again, or enter a relay address below.",
        ["своего бота"] = "your bot",
        ["Нажимай и кликай в окне Roblox, до минуты. Закончишь: нажми {0} или кнопку выше. Ввод в других окнах не записывается."] = "Press keys and click in the Roblox window, for up to a minute. When done, press {0} or the button above. Input in other windows isn't recorded.",
        ["Записано шагов: {0}, длительность {1}. Проверить можно кнопкой «Сделать сейчас»."] = "Steps recorded: {0}, duration {1}. You can test it with the “Do it now” button.",
        ["Запись длится до минуты. Записываются только клавиши и клики в окне Roblox."] = "Recording lasts up to a minute. Only keys and clicks in the Roblox window are recorded.",
        ["Нужна ссылка вида roblox.com/games/123456/... или номер игры. Короткие ссылки roblox.com/share не подойдут."] = "A link like roblox.com/games/123456/... or a game number is required. Short roblox.com/share links won't work.",
        ["Зайду сама, если в журнале Roblox появится запись об отключении: максимум 5 попыток подряд. Если закрыть окно самой, обратно не зайду. Подходит для одного окна Roblox."] = "Rejoins on its own if a disconnect record appears in the Roblox log: up to 5 attempts in a row. If you close the window yourself, it won't rejoin. Works with one Roblox window.",
        ["Кликни один раз в окне Roblox, этот клик в игру не попадёт. Через 30 секунд выбор отменится сам."] = "Click once in the Roblox window, this click doesn't reach the game. Selection cancels itself after 30 seconds.",
        ["Точка: {0:0}% слева и {1:0}% сверху окна Roblox. Если изменить размер окна, точка сдвинется вместе с ним, а кнопка в игре может оказаться в другом месте."] = "Point: {0:0}% from the left and {1:0}% from the top of the Roblox window. If the window is resized, the point moves with it, and a game button may end up elsewhere.",
        ["Нажми «Своя точка» и кликни один раз в окне Roblox. Приложение запомнит это место."] = "Press “Custom point” and click once in the Roblox window. The app will remember that spot.",
